const expected = ($env.WEBHOOK_BEARER_TOKEN || '').trim();
const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
const authorized = !expected || authHeader === ('Bearer ' + expected);
const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
return [{
  json: {
    headers,
    body,
    authorized
  }
}];

const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Bratislava',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  weekday: 'long'
}).formatToParts(now);

const getPart = (t) => (parts.find((p) => p.type === t) || {}).value || '';
const y = Number(getPart('year'));
const m = Number(getPart('month'));
const d = Number(getPart('day'));
const weekday = getPart('weekday');

const pad2 = (n) => String(n).padStart(2, '0');
const iso = (yy, mm, dd) => `${yy}-${pad2(mm)}-${pad2(dd)}`;
const gmailDate = (yy, mm, dd) => `${yy}/${pad2(mm)}/${pad2(dd)}`;
const daysInMonth = (yy, mm) => new Date(Date.UTC(yy, mm, 0)).getUTCDate();

const todayIso = iso(y, m, d);

// Current and next month boundaries
const nextMonthY = m === 12 ? y + 1 : y;
const nextMonthM = m === 12 ? 1 : m + 1;
const curMonthGmail = `after:${gmailDate(y, m, 1)} before:${gmailDate(nextMonthY, nextMonthM, 1)}`;

// Previous month
const prevMonthY = m === 1 ? y - 1 : y;
const prevMonthM = m === 1 ? 12 : m - 1;
const prevMonthLastDay = daysInMonth(prevMonthY, prevMonthM);
const prevMonthIso = `${iso(prevMonthY, prevMonthM, 1)} .. ${iso(prevMonthY, prevMonthM, prevMonthLastDay)}`;
const prevMonthGmail = `after:${gmailDate(prevMonthY, prevMonthM, 1)} before:${gmailDate(y, m, 1)}`;

// Quarters
const curQ = Math.ceil(m / 3);
const curQStartM = (curQ - 1) * 3 + 1;
const nextQY = curQ === 4 ? y + 1 : y;
const nextQStartM = curQ === 4 ? 1 : curQ * 3 + 1;
const curQGmail = `after:${gmailDate(y, curQStartM, 1)} before:${gmailDate(nextQY, nextQStartM, 1)}`;

const prevQ = curQ === 1 ? 4 : curQ - 1;
const prevQY = curQ === 1 ? y - 1 : y;
const prevQStartM = (prevQ - 1) * 3 + 1;
const prevQEndM = prevQ * 3;
const prevQEndDay = daysInMonth(prevQY, prevQEndM);
const prevQIso = `${iso(prevQY, prevQStartM, 1)} .. ${iso(prevQY, prevQEndM, prevQEndDay)}`;
const prevQGmail = `after:${gmailDate(prevQY, prevQStartM, 1)} before:${gmailDate(y, curQStartM, 1)}`;

// Last 7 and 30 days
const d7 = new Date(Date.UTC(y, m - 1, d - 7));
const d30 = new Date(Date.UTC(y, m - 1, d - 30));
const tomorrow = new Date(Date.UTC(y, m - 1, d + 1));
const fmtUtcGmail = (dt) => gmailDate(dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate());
const last7Gmail = `after:${fmtUtcGmail(d7)} before:${fmtUtcGmail(tomorrow)}`;
const last30Gmail = `after:${fmtUtcGmail(d30)} before:${fmtUtcGmail(tomorrow)}`;

const calendar_context = [
  `Dnes (Europe/Bratislava): ${todayIso} (${weekday})`,
  `Tento mesiac (${y}-${pad2(m)}): ${iso(y, m, 1)} .. ${iso(y, m, daysInMonth(y, m))} | Gmail: ${curMonthGmail}`,
  `Minuly mesiac (${prevMonthY}-${pad2(prevMonthM)}): ${prevMonthIso} | Gmail: ${prevMonthGmail}`,
  `Aktualny kvartal (Q${curQ} ${y}): ${iso(y, curQStartM, 1)} .. ${iso(y, curQ * 3, daysInMonth(y, curQ * 3))} | Gmail: ${curQGmail}`,
  `Minuly kvartal (Q${prevQ} ${prevQY}): ${prevQIso} | Gmail: ${prevQGmail}`,
  `Poslednych 7 dni Gmail: ${last7Gmail} | Poslednych 30 dni Gmail: ${last30Gmail}`,
  `Aktualny rok ${y}: ${y}-01-01 .. ${y}-12-31 | Minuly rok ${y - 1}: ${y - 1}-01-01 .. ${y - 1}-12-31`
].join('\n');

return [{
  json: {
    ...$json,
    today_iso: todayIso,
    current_quarter: `Q${curQ} ${y}`,
    previous_quarter: `Q${prevQ} ${prevQY}`,
    previous_month: `${prevMonthY}-${pad2(prevMonthM)}`,
    calendar_context
  }
}];

const rawInput = typeof query === 'string' ? query : JSON.stringify(query || '');
const text = rawInput.trim();
if (!text) {
  return JSON.stringify({ error: 'Empty input passed to financial_stats_aggregator' });
}

function normCurrency(raw) {
  const c = String(raw || 'EUR').trim().toUpperCase();
  if (c === '€') return 'EUR';
  if (c === '$') return 'USD';
  if (c === 'KČ' || c === 'KC') return 'CZK';
  if (c === '£') return 'GBP';
  if (c === 'ZŁ' || c === 'ZL') return 'PLN';
  return c || 'EUR';
}

const entries = [];
let parsedJson = null;
try {
  parsedJson = JSON.parse(text);
} catch (_) {
  parsedJson = null;
}

if (Array.isArray(parsedJson)) {
  for (const item of parsedJson) {
    if (typeof item === 'number' && Number.isFinite(item)) {
      entries.push({ label: 'item', amount: item, currency: 'EUR' });
    } else if (item && typeof item === 'object') {
      const val = Number(String(item.amount ?? item.value ?? item.price ?? item.total ?? 0).replace(',', '.'));
      if (Number.isFinite(val)) {
        entries.push({
          label: String(item.label || item.name || item.title || 'item'),
          amount: val,
          currency: normCurrency(item.currency)
        });
      }
    }
  }
} else {
  const segments = text.split(/[;\n]+/).map((s) => s.trim()).filter(Boolean);
  const chunkList = segments.length > 1 ? segments : text.split(/,(?=\s*[A-Za-zÀ-žА-Яа-я€$£])/).map((s) => s.trim()).filter(Boolean);
  for (const seg of chunkList) {
    const re = /(-?\d+(?:[.,]\d{1,4})?)\s*(EUR|USD|CZK|GBP|PLN|Kč|Kc|zł|zl|€|\$|£)?/gi;
    let match;
    const matches = [];
    while ((match = re.exec(seg)) !== null) {
      const numStr = match[1].replace(',', '.');
      const num = Number(numStr);
      if (Number.isFinite(num)) {
        matches.push({ num, cur: match[2], idx: match.index });
      }
    }
    if (matches.length > 0) {
      // Prefer match with explicit currency or last numeric value in the segment
      const picked = matches.find((x) => x.cur) || matches[matches.length - 1];
      const curFallback = (seg.match(/(EUR|USD|CZK|GBP|PLN|Kč|Kc|zł|zl|€|\$|£)/i) || [])[1];
      const label = seg.slice(0, picked.idx).replace(/[:\-–]+$/, '').trim() || 'item';
      entries.push({
        label,
        amount: picked.num,
        currency: normCurrency(picked.cur || curFallback || 'EUR')
      });
    }
  }
}

if (entries.length === 0) {
  return JSON.stringify({ error: 'No numeric amounts found in input', raw: text.slice(0, 200) });
}

const byCurrency = {};
for (const e of entries) {
  if (!byCurrency[e.currency]) {
    byCurrency[e.currency] = { centsList: [], items: [] };
  }
  const cents = Math.round(e.amount * 100);
  byCurrency[e.currency].centsList.push(cents);
  byCurrency[e.currency].items.push({ label: e.label, amount: Number((cents / 100).toFixed(2)) });
}

const summary_by_currency = {};
for (const [cur, bucket] of Object.entries(byCurrency)) {
  const list = bucket.centsList;
  const sumCents = list.reduce((a, b) => a + b, 0);
  const minCents = Math.min(...list);
  const maxCents = Math.max(...list);
  const avgCents = Math.round(sumCents / list.length);
  const total = Number((sumCents / 100).toFixed(2));
  summary_by_currency[cur] = {
    count: list.length,
    total,
    average: Number((avgCents / 100).toFixed(2)),
    min: Number((minCents / 100).toFixed(2)),
    max: Number((maxCents / 100).toFixed(2)),
    net_if_20pct_dph: Number((total / 1.2).toFixed(2)),
    net_if_23pct_dph: Number((total / 1.23).toFixed(2)),
    items: bucket.items
  };
}

return JSON.stringify({
  total_entries: entries.length,
  currencies: Object.keys(summary_by_currency),
  summary_by_currency
});

const qRaw = String(typeof query === 'string' ? query : JSON.stringify(query || '')).trim().toLowerCase();

const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Bratislava',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(now);
const getPart = (t) => Number((parts.find((p) => p.type === t) || {}).value);
const y = getPart('year');
const m = getPart('month');
const d = getPart('day');

const pad2 = (n) => String(n).padStart(2, '0');
const iso = (yy, mm, dd) => `${yy}-${pad2(mm)}-${pad2(dd)}`;
const gm = (yy, mm, dd) => `${yy}/${pad2(mm)}/${pad2(dd)}`;
const dim = (yy, mm) => new Date(Date.UTC(yy, mm, 0)).getUTCDate();

function buildMonth(yy, mm, label) {
  const nextY = mm === 12 ? yy + 1 : yy;
  const nextM = mm === 12 ? 1 : mm + 1;
  return {
    period: label,
    start_date: iso(yy, mm, 1),
    end_date: iso(yy, mm, dim(yy, mm)),
    days_count: dim(yy, mm),
    gmail_query: `after:${gm(yy, mm, 1)} before:${gm(nextY, nextM, 1)}`
  };
}

function buildQuarter(yy, qNum, label) {
  const startM = (qNum - 1) * 3 + 1;
  const endM = qNum * 3;
  const nextY = qNum === 4 ? yy + 1 : yy;
  const nextM = qNum === 4 ? 1 : endM + 1;
  const startDt = Date.UTC(yy, startM - 1, 1);
  const endDt = Date.UTC(nextY, nextM - 1, 1);
  return {
    period: label,
    start_date: iso(yy, startM, 1),
    end_date: iso(yy, endM, dim(yy, endM)),
    days_count: Math.round((endDt - startDt) / 86400000),
    gmail_query: `after:${gm(yy, startM, 1)} before:${gm(nextY, nextM, 1)}`
  };
}

let res = null;
const qMatch = qRaw.match(/q([1-4])(?:\s*(\d{4}))?/i);
const ymMatch = qRaw.match(/(\d{4})-(\d{2})/);

if (qMatch) {
  const qn = Number(qMatch[1]);
  const qy = qMatch[2] ? Number(qMatch[2]) : y;
  res = buildQuarter(qy, qn, `Q${qn} ${qy}`);
} else if (ymMatch) {
  const yy = Number(ymMatch[1]);
  const mm = Number(ymMatch[2]);
  if (mm >= 1 && mm <= 12) res = buildMonth(yy, mm, `${yy}-${pad2(mm)}`);
} else if (/minul[ýy]\s*kvart|minul[ýy]\s*štvrť|прошл\S*\s*кварт|last\s*quarter|previous\s*quarter/.test(qRaw)) {
  const curQ = Math.ceil(m / 3);
  const prevQ = curQ === 1 ? 4 : curQ - 1;
  const prevQY = curQ === 1 ? y - 1 : y;
  res = buildQuarter(prevQY, prevQ, `Q${prevQ} ${prevQY}`);
} else if (/tento\s*kvart|aktu[áa]ln\S*\s*kvart|текущ\S*\s*кварт|эт\S*\s*кварт|this\s*quarter|current\s*quarter/.test(qRaw)) {
  const curQ = Math.ceil(m / 3);
  res = buildQuarter(y, curQ, `Q${curQ} ${y}`);
} else if (/minul[ýy]\s*mes|прошл\S*\s*мес|last\s*month|previous\s*month/.test(qRaw)) {
  const pm = m === 1 ? 12 : m - 1;
  const py = m === 1 ? y - 1 : y;
  res = buildMonth(py, pm, `${py}-${pad2(pm)}`);
} else if (/tento\s*mes|текущ\S*\s*мес|эт\S*\s*мес|this\s*month|current\s*month/.test(qRaw)) {
  res = buildMonth(y, m, `${y}-${pad2(m)}`);
} else if (/minul[ýy]\s*rok|прошл\S*\s*год|last\s*year|previous\s*year/.test(qRaw)) {
  res = {
    period: String(y - 1),
    start_date: `${y - 1}-01-01`,
    end_date: `${y - 1}-12-31`,
    days_count: ((y - 1) % 4 === 0 && ((y - 1) % 100 !== 0 || (y - 1) % 400 === 0)) ? 366 : 365,
    gmail_query: `after:${y - 1}/01/01 before:${y}/01/01`
  };
} else if (/tento\s*rok|текущ\S*\s*год|эт\S*\s*год|this\s*year|current\s*year/.test(qRaw)) {
  res = {
    period: String(y),
    start_date: `${y}-01-01`,
    end_date: `${y}-12-31`,
    days_count: (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)) ? 366 : 365,
    gmail_query: `after:${y}/01/01 before:${y + 1}/01/01`
  };
} else if (/včera|вчера|yesterday/.test(qRaw)) {
  const yest = new Date(Date.UTC(y, m - 1, d - 1));
  const tod = new Date(Date.UTC(y, m - 1, d));
  const yStr = iso(yest.getUTCFullYear(), yest.getUTCMonth() + 1, yest.getUTCDate());
  res = {
    period: 'yesterday',
    start_date: yStr,
    end_date: yStr,
    days_count: 1,
    gmail_query: `after:${gm(yest.getUTCFullYear(), yest.getUTCMonth() + 1, yest.getUTCDate())} before:${gm(tod.getUTCFullYear(), tod.getUTCMonth() + 1, tod.getUTCDate())}`
  };
} else if (/týžd|недел|week/.test(qRaw)) {
  const daysBack = /minul|прошл|last|prev/.test(qRaw) ? 14 : 7;
  const startDt = new Date(Date.UTC(y, m - 1, d - daysBack));
  const endDt = new Date(Date.UTC(y, m - 1, daysBack === 14 ? d - 7 : d + 1));
  const endIncl = new Date(Date.UTC(endDt.getUTCFullYear(), endDt.getUTCMonth(), endDt.getUTCDate() - 1));
  res = {
    period: qRaw,
    start_date: iso(startDt.getUTCFullYear(), startDt.getUTCMonth() + 1, startDt.getUTCDate()),
    end_date: iso(endIncl.getUTCFullYear(), endIncl.getUTCMonth() + 1, endIncl.getUTCDate()),
    days_count: Math.round((endDt - startDt) / 86400000),
    gmail_query: `after:${gm(startDt.getUTCFullYear(), startDt.getUTCMonth() + 1, startDt.getUTCDate())} before:${gm(endDt.getUTCFullYear(), endDt.getUTCMonth() + 1, endDt.getUTCDate())}`
  };
} else {
  res = {
    period: 'today',
    today: iso(y, m, d),
    current_quarter: `Q${Math.ceil(m / 3)} ${y}`,
    note: 'Could not match specific period phrase; use today or Q1..Q4 YYYY format.'
  };
}

return JSON.stringify({ today: iso(y, m, d), timezone: 'Europe/Bratislava', ...res });

