const reqBody = $('Check Bearer Auth').first().json.body || {};
const sessionId = String(reqBody.sessionId || 'default-session');
const agentOutput = $json.output || $json.text || $json.response || '';
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];

const usedToolsSet = new Set();
const sources = [];
const seenSources = new Set();

function pushSource(item) {
  if (!item || typeof item !== 'object') return;
  const meta = item.metadata || item.payload || item;
  const filename = meta.filename || meta.source || item.filename || '';
  const category = meta.category || item.category || '';
  const doc_type = meta.doc_type || item.doc_type || '';
  const snippetRaw = item.pageContent || item.text || item.snippet || meta.text || '';
  const snippet = String(snippetRaw).trim().slice(0, 280);
  if (!filename && !snippet) return;
  const key = `${filename}|${snippet.slice(0, 80)}`;
  if (seenSources.has(key)) return;
  seenSources.add(key);
  sources.push({
    filename: String(filename || 'unknown'),
    category: String(category || ''),
    doc_type: String(doc_type || ''),
    snippet
  });
}

for (const step of steps) {
  const toolName = step && step.action && step.action.tool ? String(step.action.tool) : '';
  if (toolName) usedToolsSet.add(toolName);

  const obs = step ? step.observation : null;
  if (!obs) continue;

  let parsed = obs;
  if (typeof obs === 'string') {
    try {
      parsed = JSON.parse(obs);
    } catch (_) {
      parsed = null;
    }
  }
  if (Array.isArray(parsed)) {
    for (const entry of parsed) pushSource(entry);
  } else if (parsed && typeof parsed === 'object') {
    if (Array.isArray(parsed.documents)) {
      for (const doc of parsed.documents) pushSource(doc);
    } else if (Array.isArray(parsed.results)) {
      for (const doc of parsed.results) pushSource(doc);
    } else {
      pushSource(parsed);
    }
  }
}

return [{
  json: {
    status: 'ok',
    answer: String(agentOutput).trim(),
    used_tools: Array.from(usedToolsSet),
    sources,
    sessionId
  }
}];
